// Translator, pronunciation and spaced-repetition vocabulary practice.
// This is an honest offline phrasebook lookup, not a generative translation API.
const phraseIndex={
"hola, ¿cómo estás?":["Spanish","Russian","Привет, как дела?"],
"hello, how are you?":["English","Russian","Привет, как дела?"],
"привет, как дела?":["Russian","Spanish","Hola, ¿cómo estás?"],
"me llamo…":["Spanish","Russian","Меня зовут…"],
"my name is…":["English","Russian","Меня зовут…"],
"меня зовут…":["Russian","Spanish","Me llamo…"],
"quisiera un café, por favor.":["Spanish","Russian","Я бы хотел(а) кофе, пожалуйста."],
"i would like a coffee, please.":["English","Russian","Я бы хотел(а) кофе, пожалуйста."],
"я бы хотел(а) кофе, пожалуйста.":["Russian","Spanish","Quisiera un café, por favor."],
"¿cuánto cuesta?":["Spanish","Russian","Сколько это стоит?"],
"how much does it cost?":["English","Russian","Сколько это стоит?"],
"сколько это стоит?":["Russian","Spanish","¿Cuánto cuesta?"],
"no entiendo. ¿puedes repetir, por favor?":["Spanish","Russian","Я не понимаю. Можешь повторить, пожалуйста?"],
"i don't understand. could you repeat that, please?":["English","Russian","Я не понимаю. Не могли бы вы повторить?"],
"estoy aprendiendo español.":["Spanish","Russian","Я учу испанский."],
"i am learning english.":["English","Russian","Я учу английский."],
"buenos días":["Spanish","English","Good morning"],
"gracias":["Spanish","English","Thank you"],
"por favor":["Spanish","English","Please"],
"perdón":["Spanish","English","Excuse me / Sorry"],
"buenas noches":["Spanish","English","Good evening / Good night"],
"¿dónde está el baño?":["Spanish","English","Where is the bathroom?"],
"necesito ayuda":["Spanish","English","I need help"],
"hola":["Spanish","English","Hello"],
"adiós":["Spanish","English","Goodbye"],
"thank you":["English","Spanish","Gracias"],
"good morning":["English","Spanish","Buenos días"],
"please":["English","Spanish","Por favor"],
"where is the bathroom?":["English","Spanish","¿Dónde está el baño?"],
"i need help":["English","Spanish","Necesito ayuda"],
"hello":["English","Spanish","Hola"],
"goodbye":["English","Spanish","Adiós"]
};
let lastTranslation=null;
function detectPhraseLanguage(text){const s=text.toLowerCase();if(/[а-яё]/i.test(s))return"Russian";if(/[áéíóúñ¿¡]/i.test(s)||["hola","gracias","por favor","buenos","dónde"].some(x=>s.includes(x)))return"Spanish";if(["guten","danke","bitte","ich"].some(x=>s.includes(x)))return"German";if(["bonjour","merci","s'il"].some(x=>s.includes(x)))return"French";return"English"}
function translateOffline(text,from,to){const norm=text.trim().toLowerCase();if(!norm)return null;let hit=phraseIndex[norm];if(hit&&(from==="auto"||from===hit[0])&&(to===hit[1]||to==="Auto"))return{source:hit[0],target:hit[1],translation:hit[2],exact:true};const detected=from==="auto"?detectPhraseLanguage(text):from;const candidates=Object.entries(phraseIndex).filter(([k,v])=>v[0]===detected&&v[1]===to);const partial=candidates.find(([k])=>norm===k||norm.replace(/[.!?]+$/,"")===k.replace(/[.!?]+$/,""));if(partial)return{source:detected,target:to,translation:partial[1][2],exact:true};return{source:detected,target:to,translation:"This phrase is not in the offline phrasebook yet. Try a shorter common phrase, or add your own translation manually.",exact:false}}
function speakText(text,language){if(!("speechSynthesis"in window)){toast("Speech is not supported in this browser");return}const map={Spanish:"es-ES",English:"en-US",Russian:"ru-RU",German:"de-DE",French:"fr-FR",Italian:"it-IT",Portuguese:"pt-PT",Japanese:"ja-JP",Korean:"ko-KR",Chinese:"zh-CN"};const utterance=new SpeechSynthesisUtterance(text);utterance.lang=map[language]||language;window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance)}
$("#translateBtn")?.addEventListener("click",()=>{const text=$("#translateInput").value.trim();if(!text){toast("Enter a word or sentence first");return}const result=translateOffline(text,$("#translateFrom").value,$("#translateTo").value);lastTranslation={...result,original:text};$("#translationResult").hidden=false;$("#translationText").textContent=result.translation;$("#translationNote").textContent=result.exact?"Offline phrasebook match · "+result.source+" → "+result.target:"Offline phrasebook has no match · no external service used";$("#saveTranslation").disabled=!result.exact;});
$("#swapTranslate")?.addEventListener("click",()=>{const a=$("#translateFrom"),b=$("#translateTo");if(a.value==="auto")a.value=state.learning;const old=a.value;a.value=b.value;b.value=old;});
$("#speakTranslation")?.addEventListener("click",()=>{if(lastTranslation)speakText(lastTranslation.translation,lastTranslation.target)});
$("#saveTranslation")?.addEventListener("click",()=>{if(!lastTranslation?.exact)return;const item={id:Date.now(),word:lastTranslation.original,meaning:lastTranslation.translation,example:"",mastered:false,createdAt:Date.now(),nextReview:Date.now(),interval:0};if(state.words.some(w=>w.word.toLowerCase()===item.word.toLowerCase())){toast("Already saved");return}state.words.unshift(item);save();renderWords();toast(tr("wordAdded"))});
function dueWords(){return state.words.filter(w=>!w.mastered&&(!w.nextReview||w.nextReview<=Date.now()))}
function updateReviewDue(){const el=$("#reviewDueLabel");if(el)el.textContent=dueWords().length+" words due"}
function startWordReview(){
 const box=$("#reviewExercise"), due=dueWords();
 box.hidden=false; box.innerHTML="";
 if(!due.length){box.textContent="You are all caught up! Add words or come back later.";return;}
 let index=0,correct=0;
 function show(){
  box.innerHTML="";
  const w=due[index];
  const head=document.createElement("p");head.className="eyebrow";head.textContent="WORD "+(index+1)+" OF "+due.length;
  const prompt=document.createElement("h2");prompt.textContent="What does “"+w.word+"” mean?";
  const choices=document.createElement("div");choices.className="review-options";
  const feedback=document.createElement("p");feedback.className="quiz-feedback";
  const next=document.createElement("button");next.className="primary-btn";next.textContent=index===due.length-1?"Finish review":"Next word";next.disabled=true;
  const pool=state.words.filter(x=>x.id!==w.id&&x.meaning).sort(()=>Math.random()-.5).slice(0,3);
  [w,...pool].sort(()=>Math.random()-.5).forEach(o=>{
   const b=document.createElement("button");b.className="secondary-btn";b.textContent=o.meaning;
   b.addEventListener("click",()=>{
    if(next.disabled===false)return;
    choices.querySelectorAll("button").forEach(x=>x.disabled=true);
    if(o.id===w.id){correct++;b.classList.add("answer-correct");w.interval=Math.max(1,(w.interval||0)*2||1);w.nextReview=Date.now()+w.interval*86400000;w.reviewCount=(w.reviewCount||0)+1;feedback.textContent="Correct! Next review in "+w.interval+" day(s).";}
    else{b.classList.add("answer-wrong");w.interval=0;w.nextReview=Date.now()+10*60*1000;feedback.textContent="Correct answer: "+w.meaning;}
    save();next.disabled=false;
   });
   choices.append(b);
  });
  next.addEventListener("click",()=>{
   index++;
   if(index<due.length){show();}
   else{box.innerHTML="<h2>Review complete 🎉</h2><p>You got "+correct+" / "+due.length+" correct.</p>";renderWords();}
  });
  box.append(head,prompt,choices,feedback,next);
 }
 show();box.scrollIntoView({behavior:"smooth",block:"center"});
}
$("#startReview")?.addEventListener("click",startWordReview);

/* Interactive mini-games and resilient navigation */
(function(){
 const stage=document.getElementById('arcadeStage');if(!stage)return;
 const games={picture:{question:'Which word means “apple”?',choices:['la casa','la manzana','el libro'],answer:'la manzana',hint:'A red or green fruit.'},crossword:{question:'Complete the Spanish word for SUN (3 letters).',clue:'It shines in the sky.',answer:'SOL'},route:{question:'Mia is at the café. How does she ask for water?',choices:['Quiero agua, por favor.','¿Dónde está el tren?','Me llamo Mia.'],answer:'Quiero agua, por favor.',hint:'Agua means water.'}};
 let current='picture';
 function show(){const g=games[current];if(current==='crossword'){stage.innerHTML='<div class="arcade-prompt"><div class="arcade-art">☀️</div><div><p class="eyebrow">MINI CROSSWORD</p><h3>'+g.question+'</h3><p class="muted">'+g.clue+'</p></div></div><div class="crossword-entry"><input id="crosswordAnswer" maxlength="3" placeholder="___" aria-label="Three-letter answer"><button class="primary-btn" id="checkCrossword">Check</button></div><p class="arcade-feedback" id="arcadeFeedback"></p>';document.getElementById('checkCrossword').addEventListener('click',()=>check(document.getElementById('crosswordAnswer').value.trim().toUpperCase(),g.answer));}else{stage.innerHTML='<div class="arcade-prompt"><div class="arcade-art">'+(current==='picture'?'🍎':'🦊')+'</div><div><p class="eyebrow">'+(current==='picture'?'LOOK & LEARN':'MIA’S CITY ROUTE')+'</p><h3>'+g.question+'</h3><p class="muted">'+g.hint+'</p></div></div><div class="arcade-choices">'+g.choices.map(x=>'<button class="arcade-choice" data-answer="'+x.replace(/"/g,'&quot;')+'">'+x+'</button>').join('')+'</div><p class="arcade-feedback" id="arcadeFeedback"></p>';stage.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>check(b.dataset.answer,g.answer)));}}
 function check(value,answer){const f=document.getElementById('arcadeFeedback');if(value.toLowerCase()===answer.toLowerCase()){f.textContent='Correct! +10 XP ⭐';f.classList.add('good');const s=JSON.parse(localStorage.getItem('lm-state')||'{}');s.xp=(Number(s.xp)||0)+10;localStorage.setItem('lm-state',JSON.stringify(s));const xp=document.getElementById('homeXp');if(xp)xp.textContent=s.xp+' XP';stage.querySelectorAll('button,input').forEach(x=>x.disabled=true);}else{f.textContent='Not quite — try again!';f.classList.remove('good');}}
 document.querySelectorAll('.arcade-tab').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.game;document.querySelectorAll('.arcade-tab').forEach(x=>x.classList.toggle('active',x===b));show();}));show();
})();
document.addEventListener('click',function(e){const nav=e.target.closest('[data-page]');if(nav){const page=nav.dataset.page;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'});}},true);
